@@ -657,0 +707,32 @@
+// Store Vector with narrowing (int to byte)
+
+instruct storeV_narrow_ItoB(vmemA_ItoB mem, vReg src) %{
+  predicate(UseSVE > 0 &&
+            Matcher::vector_element_basic_type(n->in(MemNode::ValueIn)) == T_BYTE &&
+            Matcher::vector_length_in_bytes(n->in(MemNode::ValueIn)->in(1)) == MaxVectorSize);
+  match(Set mem (StoreVector mem (VectorCastI2X src)));
+  format %{ "storeV_narrow_ItoB $mem, $src\t# vector (sve)" %}
+  ins_encode %{
+    loadStoreA_predicated(masm, /* is_store */ true, $src$$FloatRegister,
+                          ptrue, T_BYTE, T_INT, $mem->opcode(),
+                          as_Register($mem$$base), $mem$$index, $mem$$scale, $mem$$disp);
+  %}
+  ins_pipe(pipe_slow);
+%}
+
+// Store Vector with narrowing (int to short)
+
+instruct storeV_narrow_ItoS(vmemA_ItoS mem, vReg src) %{
+  predicate(UseSVE > 0 &&
+            Matcher::vector_element_basic_type(n->in(MemNode::ValueIn)) == T_SHORT &&
+            Matcher::vector_length_in_bytes(n->in(MemNode::ValueIn)->in(1)) == MaxVectorSize);
+  match(Set mem (StoreVector mem (VectorCastI2X src)));
+  format %{ "storeV_narrow_ItoS $mem, $src\t# vector (sve)" %}
+  ins_encode %{
+    loadStoreA_predicated(masm, /* is_store */ true, $src$$FloatRegister,
+                          ptrue, T_SHORT, T_INT, $mem->opcode(),
+                          as_Register($mem$$base), $mem$$index, $mem$$scale, $mem$$disp);
+  %}
+  ins_pipe(pipe_slow);
+%}
+

